body[data-atom-app=market] .work{background:transparent!important;color:var(--atom-ink,#202124)!important;border-radius:0!important;border-bottom:1px solid var(--atom-line,#e6e7eb)!important}
body[data-atom-app=market] .work:last-child{border-bottom:0!important}
body[data-atom-app=market] .search button{background:var(--atom-accent,#007aff)!important;color:#fff!important;border-radius:11px!important}
body[data-atom-app=quick-notes] .note-open{background:transparent!important;color:var(--atom-ink,#202124)!important;border-radius:0!important;text-align:left}
body[data-atom-app=quick-notes] .note-entry{display:grid;grid-template-columns:1fr auto;column-gap:8px}
body[data-atom-app=quick-notes] .note-entry .note-open{grid-column:1/-1}
body[data-atom-app=quick-notes] .note-entry>p{margin:5px 0 0;font-size:10px;align-self:center}
body[data-atom-app=quick-notes] .note-entry>.actions{gap:9px;align-items:center;justify-content:end}
